int main() {
    int n, m, a, b;
    cin >> n >> m >> a >> b;

    int minCost = 1000000;

    // Try all possible numbers of m-ride tickets
    for (int i = 0; i <= n / m; i++) {
        int ridesCovered = i * m;
        int remainingRides = n - ridesCovered;
        int cost = i * b + remainingRides * a;
        minCost = min(minCost, cost);
    }

    // Also consider buying more m-ride tickets than needed (if it's cheaper)
    // The number of m-ride tickets could be ceil(n/m) or more if b < m*a
    // Actually, we should consider buying k m-ride tickets where k*m >= n
    // Let's also check the case where we buy enough m-ride tickets to cover all rides
    int fullTickets = (n + m - 1) / m; // ceil(n/m)
    int costFull = fullTickets * b;
    minCost = min(minCost, costFull);

    // But also, buying more than ceil(n/m) tickets might be cheaper if b < m*a
    // Actually, if b < m*a, then buying more tickets could be beneficial
    // Let's check: if b < m*a, then each additional m-ride ticket costs b and covers m rides
    // So we might want to buy more tickets. But since we only need n rides, buying more than ceil(n/m)
    // tickets means we're paying for rides we don't need. However, if b < m*a, it's still cheaper per ride.
    // Wait, we only need n rides. Buying k tickets covers k*m rides. We need k*m >= n.
    // The minimum k is ceil(n/m). But if b < m*a, then buying one more ticket (k+1) costs b more
    // and covers m more rides. Since we don't need those extra rides, it doesn't help unless
    // we can replace some single tickets. Actually, the optimal is to consider all k from 0 to 
    // some upper bound. Let's think differently.

    // Actually, the standard approach is:
    // Option 1: Buy all single tickets: n * a
    // Option 2: Buy some m-ride tickets and the rest single tickets
    // For i m-ride tickets (i from 0 to n/m), remaining = n - i*m, cost = i*b + remaining*a
    // Option 3: Buy enough m-ride tickets to cover all n rides: ceil(n/m) * b

    // But there's a subtlety: if b < m*a, then it's cheaper to buy m-ride tickets.
    // In that case, we might want to buy more m-ride tickets than strictly needed for the remaining rides.
    // For example, if we have 3 rides left and m=2, b=3, a=2. Then 2 single tickets cost 4, 
    // but 1 m-ride ticket costs 3 (covers 2 rides, we have 1 extra). So buying 1 m-ride ticket 
    // for 3 remaining rides costs 3, which is less than 3*2=6 or 2*2+1*2=6.
    // Wait, for 3 remaining rides with m=2: we can buy 1 m-ride ticket (covers 2) + 1 single = 3+2=5,
    // or 2 m-ride tickets (covers 4) = 6. So 5 is better.
    // But what if b=2, a=2, m=2? Then 1 m-ride + 1 single = 2+2=4, 2 m-ride = 4. Same.
    // What if b=1, a=2, m=2? Then 1 m-ride + 1 single = 1+2=3, 2 m-ride = 2. So 2 is better!
    // So we should also consider buying ceil(remaining/m) m-ride tickets for the remaining rides.

    // Let me redo this properly.
    minCost = 1000000;

    for (int i = 0; i <= n / m; i++) {
        int ridesCovered = i * m;
        int remainingRides = n - ridesCovered;
        // For remaining rides, we can either buy single tickets or m-ride tickets
        // Option A: all single
        int costA = i * b + remainingRides * a;
        // Option B: buy enough m-ride tickets to cover remaining rides
        int ticketsNeeded = (remainingRides + m - 1) / m;
        int costB = i * b + ticketsNeeded * b;
        int cost = min(costA, costB);
        minCost = min(minCost, cost);
    }

    // Also consider the case where we buy more m-ride tickets than n/m
    // Actually, the loop above with i from 0 to n/m and then considering ceil(remaining/m) 
    // m-ride tickets for the rest should cover it. But let's also just check the pure m-ride case.
    int fullTickets = (n + m - 1) / m;
    minCost = min(minCost, fullTickets * b);

    cout << minCost << endl;

    return 0;
}
